// V26.1: tags / time helpers and calendar day totals.
function parseTags(v){const out=[];for(const raw of String(v??'').split(/[\s,，、]+/)){const t=raw.replace(/^#+/,'').trim().slice(0,20);if(t&&!out.includes(t))out.push(t)}return out.slice(0,10)}
function nowTime(){const d=new Date();return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`}
function txSigned(t){const v=Math.abs(Number(t.amount||0)),tw=txTWD(v,t.account)??v;return t.kind==='expense'?-tw:t.kind==='income'?tw:0}
function dayTotals(date){let out=0,inc=0;for(const t of state.transactions){if(t.date!==date||isUnappliedPending(t))continue;const v=txSigned(t);if(v<0)out-=v;else inc+=v}return {out:Math.round(out),inc:Math.round(inc),net:Math.round(inc-out)}}
function monthProjectTotal(key){let s=0;for(const t of state.transactions)if(t.project&&t.date?.startsWith(key)&&t.kind==='expense')s+=Math.abs(txSigned(t));return Math.round(s)}
function txExtra(t){const bits=[];if(t.time)bits.push(esc(t.time));if(Array.isArray(t.tags)&&t.tags.length)bits.push(t.tags.map(x=>'#'+esc(x)).join(' '));return bits.length?' · '+bits.join(' · '):''}
function tagsHtml(t){return Array.isArray(t?.tags)?t.tags.map(x=>'#'+esc(x)).join(' '):''}
const WEEKDAYS=['週日','週一','週二','週三','週四','週五','週六'];
function renderCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),today=isoDate(new Date());let html='';for(let i=0;i<first;i++)html+='<div></div>';for(let n=1;n<=days;n++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,has=state.transactions.some(t=>t.date===date),dt=has?dayTotals(date):null,wd=new Date(y,m,n).getDay();html+=`<button type="button" class="day ${date===selectedDate?'sel':''} ${date===today?'today':''} ${wd===0||wd===6?'wkend':''}" data-date="${date}"><span class="day-num">${n}</span>${dt&&dt.net?`<small class="day-amt ${dt.net<0?'neg':'pos'}">${dt.net<0?'−':'+'}${compactNum(Math.abs(dt.net))}</small>`:has?'<i class="dot"></i>':''}</button>`}calendarGrid.innerHTML=html;calendarGrid.querySelectorAll('.day').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderCalendar();renderDaily()});monthTitle.textContent=`${y} 年 ${m+1} 月`;periodLabel.textContent=`${y}/${String(m+1).padStart(2,'0')}`}
