(async()=>{try{state=await load();lastPersistedSignatures=buildSyncSignatures(state);window.state=state;window.mozeState=state;if(todayLabel)todayLabel.textContent=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'short'});if(periodLabel)periodLabel.textContent=`${calendarMonth.getFullYear()}/${String(calendarMonth.getMonth()+1).padStart(2,'0')}`;await save(false);render();window.MozeSync?.appReady?.();}catch(err){console.error('MOZE 初始化失敗',err);alert('MOZE 初始化失敗：'+err.message)}})();

// 帳小簿 V26.4 — 報表分析頁.
// Concatenated into js/app.bundle.js right after js/app.js (tools/build-bundle.js), so it shares
// app.js globals: state, esc, money, cat, acct, acctName, txTWD, isoDate, pad2, isUnappliedPending,
// netWorthAt, addMonths, monthKey, compactNum, niceMax, netWorth, openDetail.
//
// Chart rules (dataviz): one y-axis per chart, thin marks (bars <= 24px, 4px rounded data-end,
// square baseline, 2px gap), 2px lines, >= 8px markers with a surface ring, recessive hairline grid,
// a legend for 2+ series, hover tooltips built with textContent, and every value also readable
// without hovering (ranked lists carry their figures; charts have a table view).

// Function declarations / var only: this file runs after app.js inside one script, and hoisted
// declarations stay usable even if something calls into it before this point is evaluated.
function anColors() { return { inc: '#3987e5', out: '#d95926', nw: '#199e70' }; } // validated on #1a2a3b, all pairs
function anRanges() { return [['thisMonth', '本月'], ['lastMonth', '上個月'], ['3m', '近 3 個月'], ['ytd', '今年'], ['12m', '近 12 個月'], ['custom', '自訂']]; }
var anState;
function anGetState() { if (!anState) anState = { range: 'thisMonth', from: '', to: '', kind: 'expense', account: 'all', drill: null }; return anState; }

// ---------- pure calculations (covered by tests/analysis.test.js) ----------

function anDate(s) { const [y, m, d] = String(s).split('-').map(Number); return new Date(y, m - 1, d); }
function anDays(a, b) { return Math.round((anDate(b) - anDate(a)) / 864e5) + 1; }

// Returns the selected period and the comparison period of the same length right before it.
function anRange(preset, from, to, today = new Date()) {
  const y = today.getFullYear(), m = today.getMonth();
  let s, e, months = 0;
  if (preset === 'lastMonth') { s = new Date(y, m - 1, 1); e = new Date(y, m, 0); months = 1; }
  else if (preset === '3m') { s = new Date(y, m - 2, 1); e = new Date(y, m + 1, 0); months = 3; }
  else if (preset === 'ytd') { s = new Date(y, 0, 1); e = new Date(y, 11, 31); months = 12; }
  else if (preset === '12m') { s = new Date(y, m - 11, 1); e = new Date(y, m + 1, 0); months = 12; }
  else if (preset === 'custom' && /^\d{4}-\d{2}-\d{2}$/.test(from || '') && /^\d{4}-\d{2}-\d{2}$/.test(to || '')) {
    s = anDate(from); e = anDate(to); if (s > e) [s, e] = [e, s];
  } else { s = new Date(y, m, 1); e = new Date(y, m + 1, 0); months = 1; preset = preset === 'custom' ? 'custom' : 'thisMonth'; }
  const start = isoDate(s), end = isoDate(e), days = anDays(start, end);
  let prevStart, prevEnd;
  if (months) { prevStart = isoDate(new Date(s.getFullYear(), s.getMonth() - months, 1)); prevEnd = isoDate(new Date(s.getFullYear(), s.getMonth(), 0)); }
  else { const pe = new Date(s.getFullYear(), s.getMonth(), s.getDate() - 1); prevEnd = isoDate(pe); prevStart = isoDate(new Date(pe.getFullYear(), pe.getMonth(), pe.getDate() - days + 1)); }
  const todayIso = isoDate(today);
  // days elapsed in the period (for "per day" averages of a period that is still running)
  const elapsed = todayIso < start ? 0 : todayIso >= end ? days : anDays(start, todayIso);
  return { preset, start, end, days, elapsed, prevStart, prevEnd };
}

function anValue(t, v) { const n = Math.abs(Number(v ?? t.amount ?? 0)); return txTWD(n, t.account) ?? n; }

// Income / expense transactions in [start, end], optionally limited to one account.
function anTxs(start, end, account = 'all') {
  return (state.transactions || []).filter(t =>
    (t.kind === 'expense' || t.kind === 'income') && !isUnappliedPending(t) &&
    t.date >= start && t.date <= end && (account === 'all' || String(t.account) === String(account)));
}

function anTotals(start, end, account = 'all', elapsedDays = 0) {
  let out = 0, inc = 0, nOut = 0, nInc = 0;
  for (const t of anTxs(start, end, account)) {
    if (t.kind === 'expense') { out += anValue(t); nOut++; } else { inc += anValue(t); nInc++; }
  }
  const days = elapsedDays || anDays(start, end);
  return { out: Math.round(out), inc: Math.round(inc), net: Math.round(inc - out), nOut, nInc, perDay: days ? Math.round(out / days) : 0 };
}

// A transaction's amount per category (splits respected), in TWD.
function anParts(t) {
  if (Array.isArray(t.splits) && t.splits.length) return t.splits.map(s => [s.category, anValue(t, s.amount)]);
  return [[t.category, anValue(t)]];
}
function anTopCategory(id) { const c = (state.categories || []).find(x => String(x.id) === String(id)); return c?.parentId ? String(c.parentId) : String(id ?? ''); }

// Ranked rows; the tail past `limit` folds into one "其他" row.
function anRank(map, limit = 10) {
  const total = [...map.values()].reduce((s, r) => s + r.amount, 0);
  let rows = [...map.values()].filter(r => r.amount > 0).sort((a, b) => b.amount - a.amount);
  if (rows.length > limit) {
    const rest = rows.slice(limit - 1);
    rows = rows.slice(0, limit - 1);
    rows.push({ id: '__other', name: `其他（${rest.length} 項）`, icon: '…', amount: rest.reduce((s, r) => s + r.amount, 0), count: rest.reduce((s, r) => s + r.count, 0), other: true });
  }
  return { total: Math.round(total), rows: rows.map(r => ({ ...r, amount: Math.round(r.amount), share: total ? r.amount / total : 0 })) };
}
function anAdd(map, key, base, v) { const r = map.get(key) || { ...base, amount: 0, count: 0 }; r.amount += v; r.count += 1; map.set(key, r); }

// Category ranking. drill = a main category id → its subcategories (the main itself as "（未分子類）").
function anByCategory(start, end, kind, account = 'all', drill = null, limit = 10) {
  const map = new Map();
  for (const t of anTxs(start, end, account)) {
    if (t.kind !== kind) continue;
    for (const [cid, v] of anParts(t)) {
      const top = anTopCategory(cid);
      if (drill && top !== String(drill)) continue;
      const key = drill ? String(cid) : top;
      const c = cat(key);
      const name = drill && key === String(drill) ? c.name + '（未分子類）' : c.name;
      const hasChildren = !drill && (state.categories || []).some(x => String(x.parentId) === key);
      anAdd(map, key, { id: key, name, icon: c.icon, drillable: hasChildren }, v);
    }
  }
  return anRank(map, limit);
}

function anByKey(start, end, kind, account, keyOf, limit = 8) {
  const map = new Map();
  for (const t of anTxs(start, end, account)) {
    if (t.kind !== kind) continue;
    for (const k of keyOf(t)) if (k) anAdd(map, k, { id: k, name: k }, anValue(t));
  }
  return anRank(map, limit);
}
function anMerchants(s, e, k, a) { return anByKey(s, e, k, a, t => [t.merchant || '']); }
function anTags(s, e, k, a) { return anByKey(s, e, k, a, t => (Array.isArray(t.tags) ? t.tags : []).map(x => '#' + x)); }
function anAccounts(s, e, k, a) { return anByKey(s, e, k, a, t => [acct(t.account).name || '未知帳戶']); }
function anProjects(s, e, k, a) { return anByKey(s, e, k, a, t => [t.project ? (state.projects.find(p => String(p.id) === String(t.project))?.name || '') : '']); }

// Buckets for the columns chart: daily for periods up to 62 days, monthly otherwise.
function anBuckets(start, end, account = 'all') {
  const daily = anDays(start, end) <= 62, map = new Map(), keys = [];
  if (daily) { for (let d = anDate(start); isoDate(d) <= end; d.setDate(d.getDate() + 1)) keys.push(isoDate(d)); }
  else { for (let k = start.slice(0, 7); k <= end.slice(0, 7); k = addMonths(k, 1)) keys.push(k); }
  for (const k of keys) map.set(k, { key: k, out: 0, inc: 0 });
  for (const t of anTxs(start, end, account)) {
    const b = map.get(daily ? t.date : t.date.slice(0, 7)); if (!b) continue;
    b[t.kind === 'expense' ? 'out' : 'inc'] += anValue(t);
  }
  return { daily, rows: keys.map(k => { const b = map.get(k); return { key: k, out: Math.round(b.out), inc: Math.round(b.inc) }; }) };
}

// Month-end net worth for every month touched by the period (at least 6 points).
function anNetWorth(start, end) {
  let first = start.slice(0, 7); const last = end.slice(0, 7);
  const keys = []; for (let k = first; k <= last; k = addMonths(k, 1)) keys.push(k);
  while (keys.length < 6) keys.unshift(addMonths(keys[0], -1));
  const nw = netWorthAt(keys);
  return keys.map((k, i) => ({ key: k, nw: nw[i] }));
}

// ---------- rendering ----------

function anBucketLabel(key, daily) { if (daily) { const [, m, d] = key.split('-'); return `${Number(m)}/${Number(d)}`; } const [y, m] = key.split('-'); return m === '01' ? `${y}` : `${Number(m)}月`; }
function anBucketTitle(key, daily) { if (daily) { const [y, m, d] = key.split('-'); return `${y}/${m}/${d}`; } const [y, m] = key.split('-'); return `${y} 年 ${Number(m)} 月`; }

// Column path: square at the baseline, 4px rounded at the data end.
function anColPath(x, y, w, h) {
  if (h <= 0) return '';
  const r = Math.min(4, w / 2, h);
  return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
}

// Grouped columns with one y-axis. series: [{key,label,color}]
function anColumnsSVG(rows, series, daily, width = 720) {
  const W = Math.max(280, Math.round(width) || 720), H = W < 520 ? 180 : 220, L = W < 520 ? 40 : 48, R = 12, T = 10, B = 24, iw = W - L - R, ih = H - T - B, n = rows.length || 1, slot = iw / n;
  const ticks = niceTicks(0, Math.max(0, ...rows.flatMap(r => series.map(s => r[s.key])))), max = ticks.hi;
  const y = v => T + ih - (v / max) * ih;
  const bw = Math.max(2, Math.min(24, (slot - 6 - 2 * (series.length - 1)) / series.length));
  const every = Math.max(1, Math.ceil(n * 40 / iw));
  let g = '';
  for (const v of ticks.ticks) { const yy = y(v); g += `<line class="cg-grid" x1="${L}" x2="${W - R}" y1="${yy}" y2="${yy}"/><text class="cg-axis" x="${L - 6}" y="${yy + 4}" text-anchor="end">${compactNum(v)}</text>`; }
  g += `<line class="cg-base" x1="${L}" x2="${W - R}" y1="${T + ih}" y2="${T + ih}"/>`;
  rows.forEach((r, i) => {
    const groupW = series.length * bw + (series.length - 1) * 2, x0 = L + slot * i + (slot - groupW) / 2;
    series.forEach((s, j) => { const v = r[s.key]; g += `<path fill="${s.color}" d="${anColPath(x0 + j * (bw + 2), y(v), bw, T + ih - y(v))}"/>`; });
    if ((n - 1 - i) % every === 0) g += `<text class="cg-label" x="${L + slot * i + slot / 2}" y="${H - 7}" text-anchor="middle">${anBucketLabel(r.key, daily)}</text>`;
    g += `<rect class="cg-hit" data-i="${i}" tabindex="0" x="${L + slot * i}" y="${T}" width="${slot}" height="${ih}"/>`;
  });
  return `<svg class="cg an-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${series.map(s => s.label).join('、')}長條圖">${g}</svg>`;
}

// Single-series line with a 10% area wash, markers r=4 with a 2px surface ring.
function anLineSVG(points, color, width = 720) {
  const W = Math.max(280, Math.round(width) || 720), H = W < 520 ? 140 : 180, L = W < 520 ? 44 : 56, R = 12, T = 12, B = 24, iw = W - L - R, ih = H - T - B, n = points.length || 1, slot = iw / n;
  const vals = points.map(p => p.v), lt = niceTicks(Math.min(...vals), Math.max(...vals), 3), a = lt.lo, b = lt.hi;
  const x = i => L + slot * i + slot / 2, y = v => T + ih - ((v - a) / (b - a)) * ih;
  const every = Math.max(1, Math.ceil(n * 40 / iw));
  let g = '';
  for (const v of lt.ticks) { const yy = y(v); g += `<line class="cg-grid" x1="${L}" x2="${W - R}" y1="${yy}" y2="${yy}"/><text class="cg-axis" x="${L - 6}" y="${yy + 4}" text-anchor="end">${compactNum(v)}</text>`; }
  if (points.length) {
    const pts = points.map((p, i) => `${x(i)},${y(p.v)}`).join(' ');
    g += `<polygon fill="${color}" fill-opacity=".10" points="${x(0)},${T + ih} ${pts} ${x(points.length - 1)},${T + ih}"/><polyline class="cg-line2" stroke="${color}" points="${pts}"/>`;
    points.forEach((p, i) => { g += `<circle class="cg-mark" fill="${color}" cx="${x(i)}" cy="${y(p.v)}" r="4"/>${(points.length - 1 - i) % every === 0 ? `<text class="cg-label" x="${x(i)}" y="${H - 7}" text-anchor="middle">${esc(p.label)}</text>` : ''}<rect class="cg-hit" data-i="${i}" tabindex="0" x="${L + slot * i}" y="${T}" width="${slot}" height="${ih + B}"/>`; });
  }
  return `<svg class="cg an-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="淨資產走勢">${g}</svg>`;
}

// One floating tooltip; contents are built with textContent (names can come from CSV).
function anTooltip() {
  let tip = document.getElementById('anTip');
  if (!tip && document.body) { tip = document.createElement('div'); tip.id = 'anTip'; tip.className = 'an-tip'; tip.hidden = true; document.body.appendChild(tip); }
  return tip;
}
function anBindTip(el, readout) {
  if (!el) return;
  const show = e => {
    const hit = e.target.closest?.('.cg-hit'); const tip = anTooltip(); if (!tip) return;
    if (!hit) { tip.hidden = true; return; }
    const info = readout(Number(hit.dataset.i)); if (!info) return;
    tip.textContent = '';
    const head = document.createElement('div'); head.className = 'an-tip-head'; head.textContent = info.title; tip.appendChild(head);
    for (const row of info.rows) {
      const line = document.createElement('div'); line.className = 'an-tip-row';
      const key = document.createElement('i'); key.style.background = row.color; line.appendChild(key);
      const val = document.createElement('b'); val.textContent = row.value; line.appendChild(val);
      const lab = document.createElement('span'); lab.textContent = row.label; line.appendChild(lab);
      tip.appendChild(line);
    }
    const r = hit.getBoundingClientRect();
    tip.hidden = false;
    tip.style.left = `${Math.min(window.innerWidth - 200, Math.max(8, r.left + r.width / 2 - 90))}px`;
    tip.style.top = `${Math.max(8, r.top + window.scrollY - tip.offsetHeight - 8)}px`;
    el.querySelectorAll('.cg-hit').forEach(x => x.classList.toggle('active', x === hit));
  };
  el.onpointermove = show; el.onfocusin = show;
  el.onpointerleave = () => { const tip = anTooltip(); if (tip) tip.hidden = true; el.querySelectorAll('.cg-hit.active').forEach(x => x.classList.remove('active')); };
}

function anRankHTML(rank, { drill = false, empty = '這段期間沒有資料' } = {}) {
  if (!rank.rows.length) return `<div class="empty">${empty}</div>`;
  const max = rank.rows[0].amount || 1;
  return `<div class="an-rank">${rank.rows.map(r => `<${drill && r.drillable ? `button type="button" data-an-drill="${esc(r.id)}"` : 'div'} class="an-rank-row">
    <span class="an-rank-name">${r.icon ? `<span class="an-rank-icon">${esc(r.icon)}</span>` : ''}<b>${esc(r.name)}</b>${drill && r.drillable ? '<span class="an-rank-more">›</span>' : ''}</span>
    <span class="an-rank-bar"><i style="width:${Math.max(1.5, r.amount / max * 100).toFixed(1)}%"></i></span>
    <span class="an-rank-fig"><b>${money(r.amount)}</b><small>${(r.share * 100).toFixed(1)}% · ${r.count} 筆</small></span>
  </${drill && r.drillable ? 'button' : 'div'}>`).join('')}</div>`;
}

function anDeltaHTML(cur, prev, upIsGood) {
  const p = pctChange(cur, prev);
  if (p === null) return '<span class="an-delta">上期無資料</span>';
  const d = cur - prev, good = d === 0 ? null : (d > 0) === upIsGood;
  return `<span class="an-delta ${good === null ? '' : good ? 'good' : 'bad'}">${d >= 0 ? '↑' : '↓'} ${Math.abs(p).toFixed(1)}% <small>vs 上期 ${money(prev)}</small></span>`;
}

function anTableHTML(rows, cols) {
  return `<details class="an-table"><summary>以表格檢視</summary><table><thead><tr>${cols.map(c => `<th>${c.label}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${cols.map(c => `<td>${c.value(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
}

function renderAnalysis() {
  const root = document.getElementById('analysisRoot'); if (!root) return;
  const cw = Math.max(0, (root.clientWidth || 0) - 38); // chart width inside a panel (18px padding each side)
  const AN_COLORS = anColors(), st = anGetState(), R = anRange(st.range, st.from, st.to);
  const cur = anTotals(R.start, R.end, st.account, R.elapsed), prev = anTotals(R.prevStart, R.prevEnd, st.account);
  const kindLabel = st.kind === 'expense' ? '支出' : '收入';
  const cats = anByCategory(R.start, R.end, st.kind, st.account, st.drill);
  const drillCat = st.drill ? cat(st.drill) : null;
  const buckets = anBuckets(R.start, R.end, st.account);
  const series = buckets.daily
    ? [{ key: st.kind === 'expense' ? 'out' : 'inc', label: kindLabel, color: st.kind === 'expense' ? AN_COLORS.out : AN_COLORS.inc }]
    : [{ key: 'out', label: '支出', color: AN_COLORS.out }, { key: 'inc', label: '收入', color: AN_COLORS.inc }];
  const nw = anNetWorth(R.start, R.end);
  const accOpts = `<option value="all">全部帳戶</option>${state.accounts.map(a => `<option value="${esc(a.id)}" ${String(a.id) === String(st.account) ? 'selected' : ''}>${acctName(a)}</option>`).join('')}`;
  const legend = series.length > 1 ? `<div class="an-legend">${series.map(s => `<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')}</div>` : '';
  const side = (title, rank) => `<div class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${kindLabel} · 合計 ${money(rank.total)}</p></div></div>${anRankHTML(rank, { empty: `沒有${title.replace('排行', '')}資料` })}</div>`;

  root.innerHTML = `
    <div class="an-filters" role="group" aria-label="報表篩選">
      <select id="anRange" aria-label="期間">${anRanges().map(([v, l]) => `<option value="${v}" ${v === st.range ? 'selected' : ''}>${l}</option>`).join('')}</select>
      <span class="an-custom" ${st.range === 'custom' ? '' : 'hidden'}><input type="date" id="anFrom" value="${esc(st.from || R.start)}" aria-label="開始日期"> – <input type="date" id="anTo" value="${esc(st.to || R.end)}" aria-label="結束日期"></span>
      <div class="seg an-kind"><label><input type="radio" name="anKind" value="expense" ${st.kind === 'expense' ? 'checked' : ''}>支出</label><label><input type="radio" name="anKind" value="income" ${st.kind === 'income' ? 'checked' : ''}>收入</label></div>
      <select id="anAccount" aria-label="帳戶">${accOpts}</select>
      <span class="hint an-period">${R.start.replace(/-/g, '/')} – ${R.end.replace(/-/g, '/')}</span>
    </div>
    <div class="metrics an-kpis">
      <article class="metric"><small>支出</small><strong>${money(cur.out)}</strong>${anDeltaHTML(cur.out, prev.out, false)}</article>
      <article class="metric"><small>收入</small><strong>${money(cur.inc)}</strong>${anDeltaHTML(cur.inc, prev.inc, true)}</article>
      <article class="metric"><small>結餘</small><strong>${cur.net < 0 ? '−' : ''}${money(Math.abs(cur.net))}</strong>${anDeltaHTML(cur.net, prev.net, true)}</article>
      <article class="metric"><small>日均支出</small><strong>${money(cur.perDay)}</strong><span class="an-delta">${R.elapsed || R.days} 天 · ${cur.nOut} 筆支出</span></article>
    </div>
    <div class="an-grid">
      <div class="panel an-wide">
        <div class="panel-head"><div><h2>${drillCat ? `${esc(drillCat.name)} · 子分類` : `${kindLabel}分類排行`}</h2><p>合計 ${money(cats.total)}${drillCat ? '' : ' · 點有「›」的分類查看子分類'}</p></div>${drillCat ? '<button type="button" class="ghost" data-an-drill="">‹ 全部分類</button>' : ''}</div>
        ${anRankHTML(cats, { drill: !drillCat, empty: `這段期間沒有${kindLabel}` })}
      </div>
      <div class="panel an-wide">
        <div class="panel-head"><div><h2>${buckets.daily ? `每日${kindLabel}` : '每月收支'}</h2><p>${buckets.daily ? '期間 62 天以內以每日顯示' : '支出與收入'}</p></div>${legend}</div>
        <div class="an-chart" id="anColumns">${anColumnsSVG(buckets.rows, series, buckets.daily, cw || 720)}</div>
        ${anTableHTML(buckets.rows.filter(r => r.out || r.inc), [{ label: buckets.daily ? '日期' : '月份', value: r => anBucketTitle(r.key, buckets.daily) }, ...series.map(s => ({ label: s.label, value: r => money(r[s.key]) }))])}
      </div>
      <div class="panel an-wide">
        <div class="panel-head"><div><h2>淨資產走勢</h2><p>每月月底淨資產（外幣依目前匯率換算）</p></div></div>
        <div class="an-chart" id="anNetWorth">${anLineSVG(nw.map(p => ({ v: p.nw, label: anBucketLabel(p.key, false) })), AN_COLORS.nw, cw || 720)}</div>
        ${anTableHTML(nw, [{ label: '月份', value: r => anBucketTitle(r.key, false) }, { label: '月底淨資產', value: r => money(r.nw) }])}
      </div>
      ${side('商家排行', anMerchants(R.start, R.end, st.kind, st.account))}
      ${side('標籤排行', anTags(R.start, R.end, st.kind, st.account))}
      ${side('帳戶排行', anAccounts(R.start, R.end, st.kind, st.account))}
      ${side('專案排行', anProjects(R.start, R.end, st.kind, st.account))}
    </div>`;

  anBindTip(document.getElementById('anColumns'), i => { const r = buckets.rows[i]; return r && { title: anBucketTitle(r.key, buckets.daily), rows: series.map(s => ({ color: s.color, value: money(r[s.key]), label: s.label })) }; });
  anBindTip(document.getElementById('anNetWorth'), i => { const r = nw[i]; return r && { title: anBucketTitle(r.key, false), rows: [{ color: AN_COLORS.nw, value: money(r.nw), label: '月底淨資產' }] }; });
  const set = patch => { anState = { ...anGetState(), ...patch }; renderAnalysis(); };
  root.querySelector('#anRange').onchange = e => set({ range: e.target.value, drill: null });
  root.querySelector('#anFrom').onchange = e => set({ from: e.target.value });
  root.querySelector('#anTo').onchange = e => set({ to: e.target.value });
  root.querySelector('#anAccount').onchange = e => set({ account: e.target.value });
  root.querySelectorAll('input[name=anKind]').forEach(r => r.onchange = () => set({ kind: r.value, drill: null }));
  root.querySelectorAll('[data-an-drill]').forEach(b => b.onclick = () => set({ drill: b.dataset.anDrill || null }));
}

// 帳小簿 V26.6 — 預算.
// Bundled after js/analysis.js (tools/build-bundle.js); uses app.js / analysis.js globals:
// state, esc, money, cat, monthKey, calendarMonth, isoDate, anTxs, anParts, anTopCategory, anValue.
// Function declarations only (hoisted), like analysis.js.
//
// Budget record: { id, scope: 'total' | 'category' | 'project', category, project, limit, name }
// Older records { id, category, limit } are read as scope 'category'.

function budgetNorm(b) {
  if (!b) return b;
  if (!['total', 'category', 'project'].includes(b.scope)) b.scope = b.project && !b.category ? 'project' : 'category';
  b.limit = Math.max(0, Number(b.limit) || 0);
  return b;
}

function budgetTitle(b) {
  if (b.name) return b.name;
  if (b.scope === 'total') return '每月總支出';
  if (b.scope === 'project') return (state.projects || []).find(p => String(p.id) === String(b.project))?.name || '未知專案';
  return cat(b.category).name;
}
function budgetIcon(b) { return b.scope === 'total' ? 'Σ' : b.scope === 'project' ? '▣' : cat(b.category).icon; }

// Month boundaries and pace for the month being viewed (calendarMonth).
function budgetMonth(key = monthKey(), today = new Date()) {
  const [y, m] = key.split('-').map(Number), start = `${key}-01`, end = isoDate(new Date(y, m, 0)), days = new Date(y, m, 0).getDate();
  const t = isoDate(today), elapsed = t < start ? 0 : t > end ? days : Number(t.slice(8, 10));
  return { key, start, end, days, elapsed, current: t >= start && t <= end };
}

// Spent (TWD) for one budget in [start, end]: expenses only, splits respected,
// a category budget includes its subcategories, unapplied pending excluded (anTxs does that).
function budgetSpent(b, start, end) {
  let sum = 0;
  for (const t of anTxs(start, end, 'all')) {
    if (t.kind !== 'expense') continue;
    if (b.scope === 'total') { sum += anValue(t); continue; }
    if (b.scope === 'project') { if (String(t.project) === String(b.project)) sum += anValue(t); continue; }
    for (const [cid, v] of anParts(t)) if (anTopCategory(cid) === String(b.category) || String(cid) === String(b.category)) sum += v;
  }
  return Math.round(sum);
}

function budgetStatus(spent, limit) {
  if (!limit) return { key: 'none', label: '未設定金額', mark: '—' };
  const r = spent / limit;
  if (r > 1) return { key: 'over', label: '已超支', mark: '!' };
  if (r >= 0.8) return { key: 'near', label: '接近上限', mark: '▲' };
  return { key: 'ok', label: '正常', mark: '✓' };
}

function budgetRows(key = monthKey(), today = new Date()) {
  const M = budgetMonth(key, today);
  return (state.budgets || []).map(budgetNorm).map(b => {
    const spent = budgetSpent(b, M.start, M.end), remaining = b.limit - spent, left = M.current ? M.days - M.elapsed + 1 : 0;
    return {
      budget: b, title: budgetTitle(b), icon: budgetIcon(b), spent, limit: b.limit, remaining,
      ratio: b.limit ? spent / b.limit : 0, pace: M.current ? M.elapsed / M.days : M.elapsed ? 1 : 0,
      perDay: left > 0 && remaining > 0 ? Math.floor(remaining / left) : 0, daysLeft: left,
      status: budgetStatus(spent, b.limit),
    };
  }).sort((a, b) => (a.budget.scope === 'total' ? -1 : 0) - (b.budget.scope === 'total' ? -1 : 0) || b.ratio - a.ratio);
}

function budgetMeterHTML(r) {
  const pct = Math.min(100, r.ratio * 100);
  return `<div class="bmeter ${r.status.key}" role="meter" aria-valuemin="0" aria-valuemax="${r.limit}" aria-valuenow="${r.spent}" aria-label="${esc(r.title)} 已用 ${Math.round(r.ratio * 100)}%"><i style="width:${pct.toFixed(1)}%"></i>${r.pace > 0 && r.pace < 1 ? `<b class="bmeter-pace" style="left:${(r.pace * 100).toFixed(1)}%" title="今天"></b>` : ''}</div>`;
}

function budgetCardHTML(r, compact = false) {
  const over = r.remaining < 0;
  return `<div class="budget-card2 ${r.status.key}">
    <div class="bc-head"><span class="bc-icon">${esc(r.icon)}</span><b>${esc(r.title)}</b><span class="bc-status ${r.status.key}"><i aria-hidden="true">${r.status.mark}</i>${r.status.label}</span></div>
    <div class="bc-fig"><strong>${money(r.spent)}</strong><span>/ ${money(r.limit)}</span><small>${Math.round(r.ratio * 100)}%</small></div>
    ${budgetMeterHTML(r)}
    <div class="bc-foot"><span>${over ? `超出 ${money(-r.remaining)}` : `剩餘 ${money(r.remaining)}`}</span>${r.daysLeft && !over ? `<span>每日可用 ${money(r.perDay)} · 剩 ${r.daysLeft} 天</span>` : ''}</div>
    ${compact ? '' : `<div class="bc-actions"><button type="button" class="secondary" data-budget-edit="${esc(r.budget.id)}">編輯</button><button type="button" class="secondary danger-btn" data-budget-del="${esc(r.budget.id)}">刪除</button></div>`}
  </div>`;
}

function renderBudgetPage() {
  const grid = document.getElementById('budgetGrid'); if (!grid) return;
  const rows = budgetRows(), M = budgetMonth();
  const head = document.getElementById('budgetSummary');
  if (head) {
    const cats = rows.filter(r => r.budget.scope === 'category'), limit = cats.reduce((s, r) => s + r.limit, 0), spent = cats.reduce((s, r) => s + r.spent, 0);
    const [y, m] = M.key.split('-');
    head.textContent = rows.length ? `${y} 年 ${Number(m)} 月 · ${rows.filter(r => r.status.key === 'over').length} 項超支 · ${rows.filter(r => r.status.key === 'near').length} 項接近上限${cats.length ? ` · 分類預算合計 ${money(spent)} / ${money(limit)}` : ''}` : '';
  }
  grid.innerHTML = rows.length ? rows.map(r => budgetCardHTML(r)).join('') : '<div class="empty">尚未設定預算。可以設定每月總支出、各分類或各專案的上限。</div>';
}

function renderBudgetOverview() {
  const box = document.getElementById('budgetOverview'); if (!box) return;
  const rows = budgetRows();
  const head = document.getElementById('budgetOverviewTotal');
  if (head) head.textContent = rows.length ? `${rows.length} 項 · ${rows.filter(r => r.status.key === 'over').length} 項超支` : '';
  box.innerHTML = rows.length ? `<div class="budget-mini">${rows.slice(0, 4).map(r => `<div class="bm-row"><div class="bm-top"><span>${esc(r.icon)} ${esc(r.title)}</span><span class="bc-status ${r.status.key}"><i aria-hidden="true">${r.status.mark}</i>${money(r.spent)} / ${money(r.limit)}</span></div>${budgetMeterHTML(r)}</div>`).join('')}</div>` : '<div class="empty">尚未設定預算</div>';
}

// ---- form (rendered inside the shared entity modal) ----
function budgetFormHTML(b) {
  const r = budgetNorm(b ? { ...b } : { scope: 'category', limit: '' });
  const opt = (v, l, cur) => `<option value="${esc(v)}" ${String(v) === String(cur) ? 'selected' : ''}>${l}</option>`;
  const mains = (state.categories || []).filter(c => c.kind !== 'income' && !c.parentId);
  const projOpts = (state.projects || []).map(p => opt(p.id, esc(p.name), r.project)).join('') || '<option value="">尚無專案</option>';
  return `<div class="seg"><label><input type="radio" name="bscope" value="total" ${r.scope === 'total' ? 'checked' : ''}>總預算</label><label><input type="radio" name="bscope" value="category" ${r.scope === 'category' ? 'checked' : ''}>分類</label><label><input type="radio" name="bscope" value="project" ${r.scope === 'project' ? 'checked' : ''}>專案</label></div>
  <div class="form-grid">
    <label class="b-cat">分類（含子分類）<select name="bcategory">${mains.map(c => opt(c.id, `${esc(c.icon)} ${esc(c.name)}`, r.category)).join('')}</select></label>
    <label class="b-proj">專案<select name="bproject">${projOpts}</select></label>
    <label>每月上限<input name="limit" type="number" min="1" step="any" required value="${esc(r.limit || '')}"></label>
    <label>名稱（可留空）<input name="bname" value="${esc(r.name || '')}" placeholder="預設使用分類或專案名稱"></label>
  </div><p class="hint">預算以月為單位，依概覽目前選擇的月份計算；外幣支出換算成新台幣，尚未確認入帳的待完成交易不計入。</p>`;
}
function budgetFormSync(root) {
  const scope = root.querySelector('input[name=bscope]:checked')?.value || 'category';
  root.querySelector('.b-cat')?.toggleAttribute('hidden', scope !== 'category');
  root.querySelector('.b-proj')?.toggleAttribute('hidden', scope !== 'project');
}
function budgetFromForm(f, old) {
  const scope = ['total', 'category', 'project'].includes(f.get('bscope')) ? f.get('bscope') : 'category';
  const limit = Math.abs(Number(f.get('limit') || 0));
  if (!limit) return { error: '請輸入每月上限' };
  if (scope === 'project' && !f.get('bproject')) return { error: '請先建立專案' };
  if (scope === 'total' && (state.budgets || []).some(b => b !== old && budgetNorm(b).scope === 'total')) return { error: '已經有一個總預算，請直接編輯它' };
  const b = { ...(old || { id: id() }), scope, limit, name: String(f.get('bname') || '').trim() };
  if (scope === 'category') { b.category = f.get('bcategory') || ''; delete b.project; }
  else if (scope === 'project') { b.project = f.get('bproject') || ''; delete b.category; }
  else { delete b.category; delete b.project; }
  return { budget: b };
}

document.addEventListener('click', async e => {
  const ed = e.target.closest?.('[data-budget-edit]');
  if (ed) { const b = (state.budgets || []).find(x => String(x.id) === String(ed.dataset.budgetEdit)); if (b) openEntity('budget', b); return; }
  const del = e.target.closest?.('[data-budget-del]');
  if (del) { const b = (state.budgets || []).find(x => String(x.id) === String(del.dataset.budgetDel)); if (!b || !confirm(`刪除預算「${budgetTitle(budgetNorm(b))}」？`)) return; state.budgets = state.budgets.filter(x => x !== b); await save(); render(); }
});

// 帳小簿 V26.7 — 分類管理.
// Bundled after js/budgets.js (tools/build-bundle.js); uses app.js globals (state, esc, cat, save, render,
// openEntity, id). Function declarations / var only (hoisted), like analysis.js and budgets.js.
//
// Category record: { id, name, icon, kind: 'expense' | 'income', parentId?, order? }
// Two levels only: a main category and its subcategories. `order` sorts siblings; missing → array order.

var catPageKind;
function catIcons() { return ['🍜', '☕', '🍱', '🛒', '🚗', '🚌', '⛽', '🏠', '💡', '📱', '👕', '💊', '🎬', '🎮', '✈️', '🎁', '📚', '🐾', '💼', '💰', '📈', '🏦', '🧾', '•']; }

function catSiblings(c) { return (state.categories || []).filter(x => x.kind === c.kind && String(x.parentId || '') === String(c.parentId || '')); }
function catSortKey(c) { const i = (state.categories || []).indexOf(c); return Number.isFinite(Number(c.order)) ? Number(c.order) : 1e6 + i; }
function catMains(kind) { return (state.categories || []).filter(c => !c.parentId && (!kind || (c.kind || 'expense') === kind)).sort((a, b) => catSortKey(a) - catSortKey(b)); }
function catChildren(main) { return (state.categories || []).filter(c => String(c.parentId) === String(main.id)).sort((a, b) => catSortKey(a) - catSortKey(b)); }

// Mains in order, each followed by its subcategories. Orphan subcategories (parent missing) are listed as mains.
function catOrdered(kind) {
  const out = [], seen = new Set();
  for (const m of catMains(kind)) { out.push(m); seen.add(m); for (const s of catChildren(m)) { out.push(s); seen.add(s); } }
  for (const c of (state.categories || [])) if (!seen.has(c) && (!kind || (c.kind || 'expense') === kind)) out.push(c);
  return out;
}
function catLabel(c) { const p = c.parentId ? (state.categories || []).find(x => String(x.id) === String(c.parentId)) : null; return p ? p.name + ' › ' + c.name : c.name; } // plain text; callers escape
function catOptionsHTML(kind, selected, { all = false } = {}) {
  return (all ? '<option value="all">全部分類</option>' : '') + catOrdered(kind).map(c => `<option value="${esc(c.id)}" ${String(c.id) === String(selected) ? 'selected' : ''}>${c.parentId ? '　└ ' : ''}${esc(c.icon)} ${esc(c.name)}</option>`).join('');
}

// Where a category is used: transactions (incl. split lines), recurring items, budgets.
function catUsage(cid) {
  const k = String(cid);
  let tx = 0;
  for (const t of (state.transactions || [])) {
    if (String(t.category) === k) tx++;
    else if (Array.isArray(t.splits) && t.splits.some(s => String(s.category) === k)) tx++;
  }
  const recurring = (state.recurring || []).filter(r => String(r.category) === k).length;
  const budgets = (state.budgets || []).filter(b => String(b.category) === k).length;
  return { tx, recurring, budgets, total: tx + recurring + budgets };
}

// Move every reference from one category to another (transactions, splits, recurring, budgets).
function catReassign(fromId, toId) {
  const f = String(fromId), to = String(toId);
  for (const t of (state.transactions || [])) {
    if (String(t.category) === f) t.category = to;
    if (Array.isArray(t.splits)) for (const s of t.splits) if (String(s.category) === f) s.category = to;
  }
  for (const r of (state.recurring || [])) if (String(r.category) === f) r.category = to;
  for (const b of (state.budgets || [])) if (String(b.category) === f) b.category = to;
}

function catMove(c, dir) {
  const list = catSiblings(c).sort((a, b) => catSortKey(a) - catSortKey(b));
  list.forEach((x, i) => { x.order = i; });
  const i = list.indexOf(c), j = i + dir;
  if (i < 0 || j < 0 || j >= list.length) return false;
  [list[i].order, list[j].order] = [list[j].order, list[i].order];
  return true;
}

function catFormHTML(c) {
  const r = c || { kind: 'expense', icon: '•' };
  const kind = r.kind || 'expense';
  const isMainWithKids = r.id && !r.parentId && catChildren(r).length;
  const parents = catMains(kind).filter(m => String(m.id) !== String(r.id));
  return `<div class="seg"><label><input type="radio" name="ckind" value="expense" ${kind === 'expense' ? 'checked' : ''} ${r.parentId ? 'disabled' : ''}>支出</label><label><input type="radio" name="ckind" value="income" ${kind === 'income' ? 'checked' : ''} ${r.parentId ? 'disabled' : ''}>收入</label></div>
  <div class="form-grid">
    <label>名稱<input name="cname" required maxlength="30" value="${esc(r.name || '')}" placeholder="例如：早餐"></label>
    <label>上層分類<select name="cparent" ${isMainWithKids ? 'disabled' : ''}><option value="">（主分類）</option>${parents.map(m => `<option value="${esc(m.id)}" ${String(m.id) === String(r.parentId) ? 'selected' : ''}>${esc(m.icon)} ${esc(m.name)}</option>`).join('')}</select></label>
    <label>圖示<input name="cicon" maxlength="4" value="${esc(r.icon || '•')}"></label>
  </div>
  <div class="cat-icons" role="group" aria-label="常用圖示">${catIcons().map(i => `<button type="button" data-cat-icon="${esc(i)}">${esc(i)}</button>`).join('')}</div>
  ${r.id && !r.__new ? `<p class="cat-form-del"><button type="button" class="secondary danger-btn" data-cat-del="${esc(r.id)}">刪除這個分類</button></p>` : ''}
  ${isMainWithKids ? '<p class="hint">這個主分類底下有子分類，不能改成子分類；改變收支類型時，子分類會一起改。</p>' : ''}`;
}
function catFormBind(root) {
  root.querySelectorAll('[data-cat-icon]').forEach(b => b.onclick = () => { const i = root.querySelector('[name=cicon]'); if (i) i.value = b.dataset.catIcon; });
  root.querySelectorAll('input[name=ckind]').forEach(r => r.onchange = () => {
    const sel = root.querySelector('[name=cparent]'); if (!sel || sel.disabled) return;
    sel.innerHTML = '<option value="">（主分類）</option>' + catMains(r.value).map(m => `<option value="${esc(m.id)}">${esc(m.icon)} ${esc(m.name)}</option>`).join('');
  });
}
function catFromForm(f, old) {
  const name = String(f.get('cname') || '').trim().slice(0, 30);
  if (!name) return { error: '請輸入分類名稱' };
  const parentId = old && !old.parentId && catChildren(old).length ? '' : String(f.get('cparent') || '');
  const parent = parentId ? (state.categories || []).find(c => String(c.id) === parentId) : null;
  if (parentId && !parent) return { error: '找不到上層分類' };
  if (parent && parent.parentId) return { error: '只能放在主分類底下（最多兩層）' };
  const kind = parent ? (parent.kind || 'expense') : (f.get('ckind') === 'income' ? 'income' : (old?.parentId ? (old.kind || 'expense') : 'expense'));
  const dup = (state.categories || []).some(c => c !== old && c.name === name && (c.kind || 'expense') === kind && String(c.parentId || '') === parentId);
  if (dup) return { error: `「${name}」已經存在` };
  const c = { ...(old || { id: id() }), name, icon: String(f.get('cicon') || '•').trim().slice(0, 4) || '•', kind };
  if (parentId) c.parentId = parentId; else delete c.parentId;
  return { category: c };
}

function catDeleteFormHTML(c) {
  const u = catUsage(c.id);
  const targets = catOrdered(c.kind || 'expense').filter(x => String(x.id) !== String(c.id));
  return `<p>「${esc(catLabel(c))}」目前用於 ${u.tx} 筆交易、${u.recurring} 個週期交易、${u.budgets} 個預算。刪除前請選擇要改用的分類：</p>
  <label class="entity-field">改用分類<select name="ctarget">${targets.map(x => `<option value="${esc(x.id)}">${x.parentId ? '　└ ' : ''}${esc(x.icon)} ${esc(x.name)}</option>`).join('')}</select></label>
  <p class="hint">這些交易、週期交易與預算會改成選擇的分類，帳戶餘額不受影響。</p>`;
}

function renderCategoryPage() {
  const grid = document.getElementById('categoryGrid'); if (!grid) return;
  const kind = catPageKind === 'income' ? 'income' : 'expense';
  const mains = catMains(kind);
  const card = m => {
    const kids = catChildren(m), u = catUsage(m.id), sib = catSiblings(m).length;
    return `<div class="cat-card">
      <div class="cat-head"><span class="cat-icon">${esc(m.icon)}</span><div><b>${esc(m.name)}</b><small>${u.tx} 筆交易${kids.length ? ` · ${kids.length} 個子分類` : ''}</small></div>
        <span class="cat-order"><button type="button" aria-label="上移" data-cat-move="-1" data-cat-id="${esc(m.id)}" ${sib < 2 ? 'disabled' : ''}>↑</button><button type="button" aria-label="下移" data-cat-move="1" data-cat-id="${esc(m.id)}" ${sib < 2 ? 'disabled' : ''}>↓</button></span></div>
      ${kids.length ? `<div class="cat-subs">${kids.map(s => `<button type="button" class="cat-sub" data-cat-edit="${esc(s.id)}" title="編輯子分類">${esc(s.icon)} ${esc(s.name)}<small>${catUsage(s.id).tx}</small></button>`).join('')}</div>` : ''}
      <div class="cat-actions"><button type="button" class="secondary" data-cat-edit="${esc(m.id)}">編輯</button><button type="button" class="secondary" data-cat-addsub="${esc(m.id)}">＋ 子分類</button><button type="button" class="secondary danger-btn" data-cat-del="${esc(m.id)}">刪除</button></div>
    </div>`;
  };
  grid.innerHTML = `<div class="seg cat-kind"><label><input type="radio" name="catPageKind" value="expense" ${kind === 'expense' ? 'checked' : ''}>支出分類</label><label><input type="radio" name="catPageKind" value="income" ${kind === 'income' ? 'checked' : ''}>收入分類</label></div>
    ${mains.length ? mains.map(card).join('') : '<div class="empty">還沒有分類</div>'}`;
  grid.querySelectorAll('input[name=catPageKind]').forEach(r => r.onchange = () => { catPageKind = r.value; renderCategoryPage(); });
}

async function catDelete(c) {
  if (catChildren(c).length) { alert(`「${c.name}」底下還有 ${catChildren(c).length} 個子分類，請先刪除或移動子分類。`); return; }
  if (catUsage(c.id).total) { openEntity('categoryDelete', c); return; }
  if (!confirm(`刪除分類「${catLabel(c)}」？`)) return;
  state.categories = state.categories.filter(x => x !== c);
  await save(); render();
}

document.addEventListener('click', async e => {
  const find = v => (state.categories || []).find(c => String(c.id) === String(v));
  const ed = e.target.closest?.('[data-cat-edit]'); if (ed) { const c = find(ed.dataset.catEdit); if (c) openEntity('category', c); return; }
  const add = e.target.closest?.('[data-cat-addsub]'); if (add) { const m = find(add.dataset.catAddsub); if (m) openEntity('category', { kind: m.kind || 'expense', parentId: m.id, icon: m.icon, __new: true }); return; }
  const del = e.target.closest?.('[data-cat-del]'); if (del) { const c = find(del.dataset.catDel); if (!c) return; if (del.closest('#entityBg')) closeModals(); catDelete(c); return; }
  const mv = e.target.closest?.('[data-cat-move]'); if (mv) { const c = find(mv.dataset.catId); if (c && catMove(c, Number(mv.dataset.catMove))) { await save(); render(); } }
});

(function(){
  const $=id=>document.getElementById(id);
  const escHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const input=$('amountInput'),display=$('amountDisplay'),keypad=$('amountKeypad');
  function syncAmount(){if(!input||!display)return;const v=input.value||'';display.textContent=v?Number(v).toLocaleString('zh-TW'):'0';}
  keypad?.addEventListener('click',e=>{const b=e.target.closest('button[data-key]');if(!b)return;const k=b.dataset.key;let v=input.value||'';if(k==='back')v=v.slice(0,-1);else{if(v==='0')v='';if(v.length<12)v+=k;}input.value=v;input.dispatchEvent(new Event('input',{bubbles:true}));syncAmount();});
  input?.addEventListener('input',syncAmount);
  function currentState(){return window.mozeState||window.state;}
  function refresh(){
    const st=currentState(),cc=$('categoryChoices'),ac=$('accountChoices'),cs=$('formCategory'),as=$('formAccount');
    if(!st||!cc||!ac||!cs||!as)return;
    const kind=document.querySelector('input[name="kind"]:checked')?.value||'expense';
    const ordered=typeof catOrdered==='function'?catOrdered():st.categories; // V26.7: user-defined order, subcategories under their main
    const categories=ordered.filter(c=>(c.kind||'expense')===kind || (kind==='transfer' && (c.kind||'expense')==='expense'));
    cs.innerHTML=categories.map(c=>`<option value="${c.id}">${escHtml(c.name)}</option>`).join('');
    if(!categories.some(c=>String(c.id)===String(cs.value)))cs.value=categories[0]?.id||'';
    cc.innerHTML=categories.map(c=>`<button type="button" class="choice-chip" data-select="formCategory" data-value="${c.id}"><span class="chip-icon">${svg(c.id)}</span><span class="choice-label">${c.parentId?'<small>└</small> ':''}${escHtml(c.name)}</span><span class="checkmark">✓</span></button>`).join('');
    ac.innerHTML=Array.from(as.options).map(o=>{const a=st.accounts.find(x=>String(x.id)===String(o.value));return `<button type="button" class="choice-chip" data-select="formAccount" data-value="${o.value}"><span class="chip-icon">${svg(accountIcon(a))}</span><span class="choice-label">${escHtml(o.text||a?.name)}</span><span class="checkmark">✓</span></button>`}).join('');
    sync();
  }
  function sync(){document.querySelectorAll('.choice-chip').forEach(b=>{const s=$(b.dataset.select);b.classList.toggle('active',!!s&&String(s.value)===String(b.dataset.value));});}
  document.addEventListener('click',e=>{const b=e.target.closest('.choice-chip');if(!b)return;const s=$(b.dataset.select);if(!s)return;s.value=b.dataset.value;s.dispatchEvent(new Event('change',{bubbles:true}));sync();});
  document.querySelectorAll('input[name="kind"]').forEach(r=>r.addEventListener('change',()=>setTimeout(refresh,0)));
  $('formCategory')?.addEventListener('change',sync);$('formAccount')?.addEventListener('change',sync);
  window.refreshEntryChoices=refresh;
  window.mozeState=window.state;
  const originalOpen=window.openTx || (typeof openTx==='function'?openTx:null);
  if(originalOpen){window.openTx=function(kind,t){originalOpen(kind,t);setTimeout(()=>{window.mozeState=window.state;syncAmount();refresh();},0);};}
  setTimeout(()=>{window.mozeState=window.state;syncAmount();refresh();},200);
})();
